function atTokenize(text){
  var raw=String(text||'').trim();
  if(!raw) return [];
  var parts=raw.split(/\s+/), out=[];
  for(var i=0;i<parts.length;i++){
    var p=parts[i];
    var m=p.match(/^([\w'\u4e00-\u9fa5-]+)([.,!?;:]*)$/);
    if(m){ out.push(m[1]); if(m[2]) for(var j=0;j<m[2].length;j++) out.push(m[2][j]); }
    else out.push(p);
  }
  return out;
}
function atHash(s, seed){
  var h=2166136261 ^ (seed||0);
  for(var i=0;i<s.length;i++){ h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h>>>0)/4294967296;
}
function atEmbed(token, dim, seed){
  var v=[];
  for(var d=0; d<dim; d++) v.push(atHash(token+'#'+d, seed)*2-1);
  return v;
}
function atDot(a,b){ var s=0; for(var i=0;i<a.length;i++) s+=a[i]*b[i]; return s; }
function atSoftmax(arr){
  if(!arr.length) return [];
  var mx=Math.max.apply(null, arr), ex=[], sum=0;
  for(var i=0;i<arr.length;i++){ var e=Math.exp(arr[i]-mx); ex.push(e); sum+=e; }
  for(var j=0;j<ex.length;j++) ex[j]=ex[j]/sum;
  return ex;
}
function atScores(tokens, head, dim, causal){
  dim = dim || 8;
  var n=tokens.length, emb=[], i, j;
  for(i=0;i<n;i++) emb.push(atEmbed(tokens[i], dim, (head||0)*7919+1));
  var scale=Math.sqrt(dim), rows=[];
  for(i=0;i<n;i++){
    var raw=[];
    for(j=0;j<n;j++){
      var s = atDot(emb[i], emb[j])/scale;
      if(i===j) s += 0.6;
      if(causal && j>i) s = -Infinity;
      raw.push(s);
    }
    var finite = raw.map(function(x){ return x===-Infinity ? -1e9 : x; });
    rows.push(atSoftmax(finite));
  }
  return rows;
}
function atRowEntropy(row){
  var h=0;
  for(var i=0;i<row.length;i++){ var p=row[i]; if(p>1e-12) h -= p*Math.log(p)/Math.LN2; }
  return Math.round(h*1000)/1000;
}
function atTopK(row, tokens, k){
  var pairs=[];
  for(var i=0;i<row.length;i++) pairs.push({ i:i, token:tokens[i], w:row[i] });
  pairs.sort(function(a,b){ return b.w-a.w || a.i-b.i; });
  return pairs.slice(0, k||3);
}
function atSummary(rows, tokens){
  if(!rows.length) return { error:'请输入至少一个 token' };
  var n=rows.length, colSum=new Array(n), i, j;
  for(i=0;i<n;i++) colSum[i]=0;
  var entTotal=0, diag=0;
  for(i=0;i<n;i++){
    entTotal += atRowEntropy(rows[i]);
    diag += rows[i][i];
    for(j=0;j<n;j++) colSum[j]+=rows[i][j];
  }
  var best=0;
  for(i=1;i<n;i++) if(colSum[i]>colSum[best]) best=i;
  return { error:null, tokens:n, avgEntropy:Math.round(entTotal/n*1000)/1000,
           selfWeight:Math.round(diag/n*1000)/1000,
           focusToken:tokens[best], focusScore:Math.round(colSum[best]/n*1000)/1000,
           maxEntropy:Math.round(Math.log(n)/Math.LN2*1000)/1000 };
}
function atCell(v){
  var t=Math.max(0, Math.min(1, v));
  return { alpha:Math.round(t*100)/100, label:(t*100).toFixed(1)+'%' };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { atTokenize:atTokenize, atHash:atHash, atEmbed:atEmbed, atDot:atDot,
    atSoftmax:atSoftmax, atScores:atScores, atRowEntropy:atRowEntropy, atTopK:atTopK,
    atSummary:atSummary, atCell:atCell };
}
if (typeof window !== 'undefined') {
  window.AttentionForgePure = { atTokenize:atTokenize, atHash:atHash, atEmbed:atEmbed, atDot:atDot,
    atSoftmax:atSoftmax, atScores:atScores, atRowEntropy:atRowEntropy, atTopK:atTopK,
    atSummary:atSummary, atCell:atCell };
}
